def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    bg = grid[0][0] if rows > 0 and grid[0][0] != 0 else 2

    # Find horizontal bars (they form contiguous segments)
    top_bar = None
    bottom_bar = None

