        c = 0
        while c < cols:
            if grid[row][c] == bg:
                c += 1
                continue

            if c + 2 >= cols:
                c += 1
                continue

            val = grid[row][c]
            if val == 0:  # 0 is reserved for bar cells in demos
                c += 1
                continue

            start = c
            end = c
            while end < cols and grid[row][end] == val and val != bg and val != 0:
                end += 1

            if end - start >= 2:
                bar_row, bar_start = row, start
                bar_end = end
                bar_val = val

                if top_bar is None:
                    top_bar = {"row": bar_row, "start": bar_start, "end": bar_end, "value": bar_val}
                else:
                    bottom_bar = {"row": bar_row, "start": bar_start, "end": bar_end, "value": bar_val}

            c = end

        if top_bar and bottom_bar:
