        # Use original bar columns, drop first column
        bridge_cols = range(top_bar["start"] + 1, top_bar["end"])

        # Bridge extends from top_bar+1 row down to bottom_bar row
        for c in bridge_cols:
            for r in range(top_bar["row"] + 1, bottom_bar["row"] + 1):
                if r < rows and c < cols and output[r][c] == bg:
                    output[r][c] = dot_color

